const RE = /^\p{Nd}$/u;
const runs = [];
let start = -1;
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  // skip surrogates: fromCodePoint works, but they aren't Nd anyway
  let isNd = false;
  try { isNd = RE.test(String.fromCodePoint(cp)); } catch (e) { isNd = false; }
  if (isNd) {
    if (start < 0) start = cp;
  } else if (start >= 0) {
    runs.push([start, cp - 1]);
    start = -1;
  }
}
if (start >= 0) runs.push([start, 0x10FFFF]);

const hex = (n) => 'U+' + n.toString(16).toUpperCase().padStart(4, '0');
console.log('total runs:', runs.length);
const bad = runs.filter(([a, b]) => (b - a + 1) % 10 !== 0);
const long = runs.filter(([a, b]) => (b - a + 1) > 10);
console.log('runs whose length is NOT a multiple of 10:', bad.length);
for (const [a, b] of bad) console.log('  NOT-MULT-10', hex(a), hex(b), 'len', b - a + 1);
console.log('runs longer than 10:', long.length);
for (const [a, b] of long) console.log('  LONG', hex(a), '..', hex(b), 'len', b - a + 1);
console.log('--- all runs ---');
for (const [a, b] of runs) console.log(hex(a), hex(b), b - a + 1);
console.log('total Nd code points:', runs.reduce((s, [a, b]) => s + b - a + 1, 0));
import fs from 'fs';
fs.writeFileSync('/tmp/ndscan/runs.json', JSON.stringify(runs));
EOF
